-- Merge the two permission helpers into one (docs/TODO.md item 1).
--
-- has_module_permission (20261107090000) and staff_can (20261106240000) both mirrored
-- DEFAULT_PERMISSIONS, each with its own copy. has_module_permission now matches
-- mergePermissions in lib/permissions.ts exactly:
--   - only active profiles (the app requires profiles.is_active = true everywhere)
--   - admin always has full clients / projects / vendors (ADMIN_DIRECTORY_MODULES)
--   - otherwise the per-user override wins per action, then the role default, else false
-- staff_can becomes a wrapper so its 18 policies keep working with one copy of the
-- defaults. Checked before writing: for all 12 profiles, staff_can and the merged rule
-- agree on every module staff_can is used with (288 combinations; only payslips, which
-- no staff_can policy uses, differed).
--
-- The defaults below must equal DEFAULT_PERMISSIONS;
-- lib/__tests__/rls-module-permission-defaults.test.ts checks the newest migration
-- that defines them.
--
-- Rollback: re-run the function definitions from 20261107090000 (has_module_permission)
-- and 20261106240000 (staff_can).

create or replace function public.has_module_permission(p_module text, p_action text)
returns boolean
language sql
stable
security definer
set search_path = public
as $fn$
  select coalesce(
    (select case
       when p.role = 'admin' and p_module in ('clients', 'projects', 'vendors') then true
       else coalesce(
         (p.permissions -> p_module ->> p_action)::boolean,
         (d.defaults -> p.role -> p_module ->> p_action)::boolean,
         false
       )
     end
     from public.profiles p
     cross join (select
